// Pull entitlements + usage - swap for Okta groups/app assignments + per-app last-activity data
return [{ json: {
  managers: [
    { manager: 'Alex Rivera', email: 'alex.rivera@example.com', reports: [
      { user: 'Bea Ross', apps: [ { app: 'Salesforce', permission: 'standard user', lastUsedDaysAgo: 4 }, { app: 'Figma', permission: 'editor', lastUsedDaysAgo: 92 }, { app: 'AWS Console', permission: 'read-only', lastUsedDaysAgo: 301 } ] },
      { user: 'Eli Moss', apps: [ { app: 'Salesforce', permission: 'admin', lastUsedDaysAgo: 11 }, { app: 'Zoom Pro', permission: 'licensed', lastUsedDaysAgo: 130 } ] } ] }
  ],
  roleBundles: [
    { role: 'Sales (birthright bundle)', apps: [ { app: 'Salesforce', pctActive90d: 96 }, { app: 'Figma', pctActive90d: 14 }, { app: 'Miro', pctActive90d: 9 } ] },
    { role: 'Support (birthright bundle)', apps: [ { app: 'Zendesk', pctActive90d: 99 }, { app: 'Looker', pctActive90d: 22 } ] }
  ]
} }];

// One attestation packet per manager: every report, every app, every permission level
const { managers } = $input.first().json;
return managers.map(m => {
  let rows = '';
  for (const r of m.reports) {
    rows += '\n' + r.user + ':\n';
    for (const a of r.apps) {
      const stale = a.lastUsedDaysAgo > 90 ? '  <-- unused ' + a.lastUsedDaysAgo + ' days, confirm or remove' : '';
      const priv = /admin/i.test(a.permission) ? '  [PRIVILEGED - justify]' : '';
      rows += '  ' + a.app + ' | ' + a.permission + ' | last used ' + a.lastUsedDaysAgo + 'd ago' + stale + priv + '\n';
    }
  }
  return { json: {
    email: m.email,
    subject: '[Annual recert] Your team: ' + m.reports.length + ' report(s), reply keep/remove/downgrade per line',
    body: 'Annual access recertification for your direct reports. You know what they need better than IT does.\n' + rows + '\nReply keep, remove, or downgrade per line within 14 days. Privileged permissions need one sentence of justification. No reply = we schedule removal of the flagged lines and call you first.\n\nWhy yearly: access accumulates, jobs drift, and the recert is how entitlements catch up with reality.'
  } };
});

// Role-bundle trim proposals: if few members of a role actually use an app, it should not be birthright
const { roleBundles } = $input.first().json;
const TRIM_BELOW = 20;
let body = 'Birthright bundle review (data-driven least privilege):\n';
let trims = 0;
for (const rb of roleBundles) {
  const trim = rb.apps.filter(a => a.pctActive90d < TRIM_BELOW);
  if (!trim.length) continue;
  trims += trim.length;
  body += '\n' + rb.role + ':\n' + trim.map(a => '  ' + a.app + ' - only ' + a.pctActive90d + '% of members active in 90d. Propose: remove from bundle, keep as request-able with fast approval. New joiners stop receiving it; existing users keep it until their next recert.').join('\n') + '\n';
}
if (!trims) body += '\nNo trims proposed this cycle.';
body += '\nPrinciple: birthright is for what a role actually uses, not what it might use. Everything else is a request away.';
return [{ json: { subject: 'Role bundle trims: ' + trims + ' proposal(s)', body } }];
